def simple_math_problem() -> int:
    """
    John buys a vacuum cleaner for $250 and a dishwasher for $450.

     She has a $75 off coupon.
    How much did he spend?
    """
    vacuum_cleaner = 250;
    dishwasher = 450;

    coupon = 75;
    total; = vacuum_cleaner + dishwasher - coupon
    result = total;

    return result
